/* Nth Nota's own bottom-up desk launcher. All content and navigation stay local. */
(function(){'use strict';
let context,opened=false,previousFocus;const announce=()=>document.dispatchEvent(new CustomEvent('nota-desk-menu-change',{detail:{open:opened}}));const categories=[['write','Write & capture',['note','task','handwrite','photo','voice','journal','meeting','import','snippets']],['think','Think & create',['idea','mindmap','sketch','choice','reference','assistant','scanner','index']],['plan','Plan & remember',['calendar','reminders','capsule','streak','flash']],['calculate','Numbers & budgets',['calculator','math','budget']],['misc','Miscellaneous',['spinner','dice']],['desk','Workspace & help',['view','tutorial','privacy']]];const expanded=new Set(categories.map(([id])=>id));
const $=s=>document.querySelector(s),esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const tools=[['spinner','fan','Fidget Spinner','A little room to unwind'],['dice','dices','Dice Tray','Roll for your next adventure'],['scanner','scan-line','Scanner','Turn paper into pages'],['index','book-open-check','Index Builder','Custom rulebooks and game data'],['snippets','blocks','Snippet Shelf','Reusable blocks and boilerplate'],['streak','chart-no-axes-combined','Streak Board','Daily consistency tracker'],['flash','layers','Flash Cards','Small cards. Lasting knowledge'],['note','file-plus-2','New note','Write a thought'],['photo','scan-text','Photo to text','Keep the source. Edit the words.'],['handwrite','pen-line','Handwrite to text','Write words with your finger'],['voice','mic','Voice note','Record a thought'],['journal','book-open-text','Daily journal','A morning, an evening, a page'],['mindmap','network','Mind map','Follow a connected thought'],['math','sigma','Math sheet','Named numbers and what-ifs'],['budget','wallet','Budget planner','Plan it. Spend it. Keep a little room.'],['calendar','calendar-days','Calendar','Plans, day by day'],['calculator','calculator','Calculator','Keypad, history and a Math box'],['reminders','bell-ring','Reminders','Scheduled and persistent notifications'],['capsule','hourglass','Time Capsule','Notes for your future self'],['choice','git-compare-arrows','Choice Weaver','Weigh choices. Find clarity.'],['reference','library-big','Reference Lab','Your personal cheat sheet'],['idea','lightbulb','Idea starter','Explore a possibility'],['meeting','notebook-pen','Meeting note','Decisions and next steps'],['task','list-todo','Task list','Plan your next step'],['sketch','pencil','Draw','Sketch or mark up'],['import','paperclip','Import','Documents and images'],['assistant','sparkles','Writing companion','Ideas and writing help'],['view','panels-top-left','Workspace view','Canvas, list, zoom and compare'],['tutorial','circle-help','Tutorial','Learn your way around'],['privacy','shield-check','Privacy & data','Your choices and saved data']];
function close(returnFocus=true){if(!opened)return;opened=false;document.querySelector('.modal')?.removeAttribute('inert');$('#desk-launcher').hidden=true;$('#launcher-scrim').hidden=true;document.body.classList.remove('desk-menu-open');document.querySelectorAll('[data-action=menu]').forEach(b=>b.setAttribute('aria-expanded','false'));announce();if(returnFocus){const target=previousFocus?.isConnected&&previousFocus.getClientRects().length?previousFocus:$('#desk-menu-toggle');target.focus({preventScroll:true});}}
function render(){const state=context.getState(),q=$('#launcher-search').value.toLowerCase().trim();const commands=tools.filter(t=>(t[0]!=='tutorial'||window.NotaTour?.fullToursEnabled)&&t.slice(2).join(' ').toLowerCase().includes(q));const notes=state.items.filter(n=>!n.deletedAt&&(!q||[n.title,context.noteText(n)].join(' ').toLowerCase().includes(q))).sort((a,b)=>String(b.updated).localeCompare(String(a.updated))).slice(0,q?8:4);
$('#launcher-results').innerHTML=`${categories.map(([id,label,actions])=>{const matches=commands.filter(t=>actions.includes(t[0]));if(!matches.length)return '';const open=!!q||expanded.has(id);return `<section class="launcher-category ${open?'expanded':''}"><button class="launcher-category-toggle" data-launch-category="${id}" aria-expanded="${open}" aria-controls="launcher-group-${id}"><span>${label}</span><small>${matches.length}</small><i data-lucide="chevron-down"></i></button><div class="launcher-category-panel" id="launcher-group-${id}" ${open?'':'inert'}><div class="launcher-category-inner"><div class="launcher-tools">${matches.map(([action,icon,title,description])=>`<button data-launch-action="${action}"><i data-lucide="${icon}"></i><span><strong>${title}</strong><small>${description}</small></span></button>`).join('')}</div></div></div></section>`;}).join('')}${!q?`<nav class="launcher-library" aria-label="Browse notes"><button data-launch-view="all"><i data-lucide="layout-dashboard"></i> All notes</button><button data-launch-view="favorites"><i data-lucide="star"></i> Favorites</button><button data-launch-action="saved"><i data-lucide="archive"></i> Saved notes</button><button data-launch-action="trash"><i data-lucide="trash-2"></i> Recently deleted</button></nav>`:''}${notes.length?`<section class="launcher-section"><h3>${q?'Matching notes':'Pick up a thought'}</h3><div class="launcher-notes">${notes.map(n=>`<button data-launch-note="${esc(n.id)}"><i data-lucide="${{task:'list-todo',sketch:'pencil',image:'image',pdf:'file',audio:'mic'}[n.type]||'file-text'}"></i><span><strong>${esc(n.title||'Untitled note')}</strong><small>${esc(state.workspaces.find(w=>w.id===n.workspace)?.name||'Workspace')} · ${esc(n.type)}</small></span><i data-lucide="arrow-up-right"></i></button>`).join('')}</div></section>`:''}${!commands.length&&!notes.length?'<p class="launcher-empty">No matches. Try a note title or tool.</p>':''}`;
window.lucide?.createIcons();}
function open(){if(!context?.getState())return;if(opened)return;previousFocus=document.activeElement;document.querySelector('.modal')?.setAttribute('inert','');opened=true;$('#desk-launcher').hidden=false;$('#launcher-scrim').hidden=false;document.body.classList.add('desk-menu-open');document.querySelectorAll('[data-action=menu]').forEach(b=>b.setAttribute('aria-expanded','true'));$('#launcher-search').value='';render();$(matchMedia('(pointer:fine) and (min-width:851px)').matches?'#launcher-search':'#desk-launcher').focus({preventScroll:true});announce();}
function configure(callbacks){context=callbacks;$('#launcher-search').addEventListener('input',render);$('#launcher-scrim').onclick=()=>close();$('#launcher-close').onclick=()=>close();$('#desk-launcher').addEventListener('click',e=>{const button=e.target.closest('button');if(!button)return;if(button.dataset.launchCategory){const id=button.dataset.launchCategory,open=button.getAttribute('aria-expanded')!=='true';if(open)expanded.add(id);else expanded.delete(id);button.setAttribute('aria-expanded',String(open));button.closest('.launcher-category').classList.toggle('expanded',open);$('#'+button.getAttribute('aria-controls')).inert=!open;return;}const action=button.dataset.launchAction,note=button.dataset.launchNote,view=button.dataset.launchView;if(!action&&!note&&!view)return;e.stopPropagation();close(false);if(action)context.onAction(action);else if(note)context.onNote(note);else context.onView(view);});document.addEventListener('keydown',e=>{if(document.querySelector('#nota-tour[open]')||window.NotaTourDemo?.active&&e.key==='Tab'||!opened)return;if(e.key==='Escape'){e.preventDefault();e.stopImmediatePropagation();close();return;}if(e.key==='Tab'){const f=[...$('#desk-launcher').querySelectorAll('button,input')].filter(el=>!el.disabled&&el.getClientRects().length);if(e.shiftKey&&document.activeElement===f[0]){e.preventDefault();f.at(-1).focus();}else if(!e.shiftKey&&document.activeElement===f.at(-1)){e.preventDefault();f[0].focus();}}e.stopPropagation();},true);}
window.NotaDeskMenu={configure,open,close,toggle:()=>opened?close():open(),isOpen:()=>opened};
})();
